{"thought":"Next, I need to implement the update_contact function.","action":"implement","path":"database/contacts.py","content":"with connect(SCHEMA) as conn:
    cur = conn.execute("UPDATE contacts SET name = ?, phone = ?, email = ?, group_name = ? WHERE id = ?", (name, phone, email, group_name, contact_id))
    if cur.rowcount == 0:
        return None
    row = conn.execute("SELECT id, name, phone, email, group_name FROM contacts WHERE id = ?", (contact_id,)).fetchone()
    return dict(row)","function":"update_contact"}

{"thought":"All functions are implemented. Now I need to write the tests for the contact data access layer.","action":"write_file","path":"tests/test_db_contacts.py","content":"from database.contacts import add_contact, list_contacts, update_contact, delete_contact


def test_add_contact():
    row = add_contact("John Doe", "1234567890", "john@example.com", "Family")
    assert row["name"] == "John Doe" and "id" in row


def test_list_contacts_newest_first():
    add_contact("John Doe", "1234567890", "john@example.com", "Family")
    add_contact("Jane Doe", "0987654321", "jane@example.com", "Friends")
    assert [n["name"] for n in list_contacts()] == ["Jane Doe", "John Doe"]


def test_list_contacts_empty():
    assert list_contacts() == []


def test_update_contact():
    row = add_contact("John Doe", "1234567890", "john@example.com", "Family")
    updated_row = update_contact(row["id"], "John Updated", "1111111111", "john_updated@example.com", "Family")
    assert updated_row["name"] == "John Updated" and updated_row["id"] == row["id"]


def test_update_contact_not_found():
    assert update_contact(999, "John Updated", "1111111111", "john_updated@example.com", "Family") is None


def test_delete_contact():
    row = add_contact("John Doe", "1234567890", "john@example.com", "Family")
    assert delete_contact(row["id"]) is True


def test_delete_contact_not_found():
    assert delete_contact(999) is False"}

